    static final String SCHEMA="tryon_test_"+UUID.randomUUID().toString().replace("-","");
    static final String BASE=System.getenv().getOrDefault("SPRING_DATASOURCE_URL","jdbc:postgresql://localhost:5433/virtualwardrobe");
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->BASE+(BASE.contains("?")?"&":"?")+"currentSchema="+SCHEMA);r.add("spring.flyway.schemas",()->SCHEMA);r.add("spring.flyway.default-schema",()->SCHEMA);r.add("app.bootstrap.email",()->"");r.add("app.bootstrap.password",()->"");r.add("app.local-data-directory",()->"work/tryon-test/"+SCHEMA);r.add("app.image-provider",()->"google");r.add("APP_GENERATION_CUSTOMER_DAILY_LIMIT",()->2);r.add("APP_GENERATION_GLOBAL_DAILY_LIMIT",()->4);r.add("APP_GENERATION_DAILY_BUDGET_USD",()->"0.50");r.add("APP_GENERATION_SAVED_LIMIT",()->1);}
    @TestConfiguration static class Fakes{@Bean @Primary ControlledProvider controlledProvider(){return new ControlledProvider();}}
    static class ControlledProvider implements ImageProvider {
        final AtomicInteger calls=new AtomicInteger(),failures=new AtomicInteger();volatile ProviderFailure.Kind failure;volatile boolean block;volatile CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);byte[] output;
        void reset(byte[] png){calls.set(0);failures.set(0);failure=null;block=false;entered=new CountDownLatch(1);release=new CountDownLatch(1);output=png;}
        public GenerationResult generate(GenerationRequest request){calls.incrementAndGet();entered.countDown();if(block)try{if(!release.await(10,TimeUnit.SECONDS))throw new ProviderFailure(ProviderFailure.Kind.UNKNOWN_OUTCOME,"Controlled timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new ProviderFailure(ProviderFailure.Kind.UNKNOWN_OUTCOME,"Controlled interrupt");}if(failures.getAndUpdate(v->Math.max(0,v-1))>0)throw new ProviderFailure(failure,"Controlled provider failure");return new GenerationResult(output,"image/png","google","gemini-nano-banana-2.1",false,new BigDecimal("0.04"),100,100,0);}
    }
    @Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired TryOnTransactions tx;@Autowired TryOnService service;@Autowired TryOnWorker worker;
    @Autowired TryOnSettings settings;@Autowired ControlledProvider provider;@Autowired CatalogService catalog;@Autowired MediaService catalogMedia;@Autowired MediaStorage storage;@Autowired ImageProcessor images;@Autowired PasswordEncoder passwords;@Autowired IdentityService identity;@Autowired RateLimits rates;@Autowired FoundationProperties foundation;
    UUID owner,other,admin,store,product;byte[] png;final Gson json=new Gson();
    @BeforeEach void setup()throws Exception{
        SecurityContextHolder.clearContext();jdbc.execute("TRUNCATE vw_account,vw_store,vw_membership,vw_category,vw_brand,vw_product,vw_media_upload,vw_tryon_consent,vw_private_media,vw_tryon_job,vw_tryon_attempt,vw_generation_day,vw_customer_generation_day,vw_task_delivery,vw_object_deletion,vw_audit_event,vw_rate_limit,SPRING_SESSION CASCADE");
        owner=account("CUSTOMER","+919111111111",false);other=account("CUSTOMER","+919222222222",false);admin=account("WORKFORCE","tryon-admin@example.test",true);store=UUID.randomUUID();jdbc.update("INSERT INTO vw_store(id,name,status) VALUES(?,'Try-on studio','ACTIVE')",store);jdbc.update("INSERT INTO vw_membership(id,store_id,account_id,role,state,accepted_at) VALUES(?,?,?,'STORE_ADMIN','ACTIVE',CURRENT_TIMESTAMP)",UUID.randomUUID(),store,admin);
        png=png();provider.reset(png);as(admin);UUID category=(UUID)catalog.category(null,Map.of("name","Test sarees")).get("id");product=(UUID)catalog.create(store,Map.of("sku","TRY-1","title","Owned synthetic saree","categoryId",category.toString(),"price","1500.00")).get("id");var auth=catalogMedia.authorize(store,product,null,"PRODUCT_IMAGE",Map.of("contentType","image/png","bytes",png.length,"kind","IMAGE"));@SuppressWarnings("unchecked")var headers=(Map<String,String>)auth.get("headers");UUID media=(UUID)auth.get("uploadId");catalogMedia.upload(media,headers.get("X-Upload-Token"),"image/png",new ByteArrayInputStream(png),png.length);catalogMedia.finalizeUpload(media);catalog.patch(store,product,Map.of("status","PUBLISHED"));as(owner);
    }
    @AfterEach void clear(){provider.release.countDown();SecurityContextHolder.clearContext();}
    @AfterAll static void removeSchema()throws Exception{try(var c=DriverManager.getConnection(BASE,System.getenv().getOrDefault("SPRING_DATASOURCE_USERNAME","virtualwardrobe"),System.getenv().getOrDefault("SPRING_DATASOURCE_PASSWORD",""));var s=c.createStatement()){s.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}}
    static byte[] png()throws Exception{var image=new BufferedImage(90,150,BufferedImage.TYPE_INT_RGB);for(int x=0;x<90;x++)for(int y=0;y<150;y++)image.setRGB(x,y,(x*341+y*117)&0xffffff);var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return out.toByteArray();}
    UUID account(String kind,String identifier,boolean superAdmin){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO vw_account(id,kind,name,normalized_identifier,password_hash,super_admin) VALUES(?,?,'Test customer',?,?,?)",id,kind,identifier,passwords.encode("ValidPassword123!"),superAdmin);return id;}
    void as(UUID id){SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(id.toString(),null,List.of()));}
    Map<String,Object> uploadBody(){return Map.of("productId",product.toString(),"fileName","owned.png","contentType","image/png","bytes",png.length,"consent",Map.of("version",settings.version(),"adult",true,"ownPhoto",true,"providerProcessing",true));}
    UUID source(){var lease=service.authorize(uploadBody());UUID id=(UUID)lease.get("uploadId");@SuppressWarnings("unchecked")var headers=(Map<String,String>)lease.get("headers");service.upload(id,headers.get("X-Upload-Token"),"image/png",new ByteArrayInputStream(png),png.length);service.finalizeUpload(id);return id;}
    Map<String,Object> intent(UUID source,String key){return Map.of("productId",product.toString(),"sourceUploadId",source.toString(),"idempotencyKey",key);}
    UUID job(){return(UUID)service.create(intent(source(),UUID.randomUUID().toString())).get("id");}
    @SuppressWarnings("unchecked") Map<String,Object> result(UUID job){return(Map<String,Object>)service.get(job).get("result");}
    Cookie login(String kind,String identifier)throws Exception{SecurityContextHolder.clearContext();return mvc.perform(post("/api/v1/auth/login").with(csrf()).contentType("application/json").content(json.toJson(Map.of("kind",kind,"identifier",identifier,"password","ValidPassword123!")))).andExpect(status().isOk()).andReturn().getResponse().getCookie("__session");}
    BigDecimal ledger(String field){return jdbc.queryForObject("SELECT "+field+" FROM vw_generation_day",BigDecimal.class);}
    @Test void actualHttpConsentAndPrivateCapabilityThenSuccessfulJobGalleryAndDownload()throws Exception{
        var customer=login("CUSTOMER","+919111111111");mvc.perform(post("/api/v1/me/try-on/uploads").cookie(customer).contentType("application/json").content(json.toJson(uploadBody()))).andExpect(status().isForbidden());
        var missing=new HashMap<>(uploadBody());missing.remove("consent");mvc.perform(post("/api/v1/me/try-on/uploads").cookie(customer).with(csrf()).contentType("application/json").content(json.toJson(missing))).andExpect(status().isConflict());
        var leaseResponse=mvc.perform(post("/api/v1/me/try-on/uploads").cookie(customer).with(csrf()).contentType("application/json").content(json.toJson(uploadBody()))).andExpect(status().isOk()).andReturn();var lease=JsonParser.parseString(leaseResponse.getResponse().getContentAsString()).getAsJsonObject();UUID source=UUID.fromString(lease.get("uploadId").getAsString());String raw=lease.get("uploadUrl").getAsString(),token=lease.getAsJsonObject("headers").get("X-Upload-Token").getAsString();
        mvc.perform(put(raw).header("X-Upload-Token",token).contentType("image/png").content(png)).andExpect(status().isNoContent());mvc.perform(post("/api/v1/me/try-on/uploads/"+source+"/finalize").cookie(customer).with(csrf())).andExpect(status().isOk());
        as(owner);var body=intent(source,UUID.randomUUID().toString());UUID id=(UUID)service.create(body).get("id");assertThat(ledger("reserved_usd")).isEqualByComparingTo("0.25");SecurityContextHolder.clearContext();assertThat(worker.run(id,1)).isTrue();as(owner);
        assertThat(service.get(id).get("state")).isEqualTo("SUCCEEDED");assertThat(tx.media(source).state()).isEqualTo("DELETED");assertThat(ledger("reserved_usd")).isZero();assertThat(ledger("committed_usd")).isEqualByComparingTo("0.25");assertThat(ledger("observed_usd")).isEqualByComparingTo("0.04");assertThat(service.create(body).get("id")).isEqualTo(id);assertThat(tx.quota().get("used")).isEqualTo(1);
        UUID output=(UUID)result(id).get("id");SecurityContextHolder.clearContext();mvc.perform(get("/api/v1/private-media/"+output+"/content")).andExpect(status().isNotFound());mvc.perform(get("/api/v1/private-media/"+source+"/content").cookie(customer)).andExpect(status().isNotFound());
        mvc.perform(get("/api/v1/private-media/"+output+"/download").cookie(customer)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.containsString("attachment")));
        as(other);assertThatThrownBy(()->service.get(id)).isInstanceOfSatisfying(ApiProblem.class,e->assertThat(e.status).isEqualTo(404));assertThatThrownBy(()->service.read(output,false)).isInstanceOf(ApiProblem.class);as(admin);assertThatThrownBy(()->service.read(output,false)).isInstanceOf(ApiProblem.class);as(owner);service.save(id);service.save(id);assertThat(tx.quota().get("saved")).isEqualTo(1);
        as(admin);catalog.archive(store,product);as(owner);@SuppressWarnings("unchecked")var items=(List<Map<String,Object>>)tx.gallery(0,20).get("items");assertThat(items.getFirst().get("currentAvailability")).isEqualTo("ARCHIVED");service.deleteGallery(output);assertThat(result(id)).isNull();assertThatThrownBy(()->service.read(output,false)).isInstanceOf(ApiProblem.class);
    }
    @Test void concurrentDuplicateIntentCreatesOneJobAndChangedFingerprintConflicts()throws Exception{
        UUID source=source();var body=intent(source,UUID.randomUUID().toString());var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);
        try{var calls=List.of(1,2).stream().map(i->pool.submit(()->{as(owner);go.await();try{return service.create(body).get("id");}finally{SecurityContextHolder.clearContext();}})).toList();go.countDown();assertThat(calls.get(0).get(10,TimeUnit.SECONDS)).isEqualTo(calls.get(1).get(10,TimeUnit.SECONDS));assertThat(jdbc.queryForObject("SELECT count(*) FROM vw_tryon_job",Integer.class)).isEqualTo(1);as(owner);assertThat(tx.quota().get("used")).isEqualTo(1);var changed=new HashMap<>(body);changed.put("sourceUploadId",UUID.randomUUID().toString());assertThatThrownBy(()->service.create(changed)).isInstanceOfSatisfying(ApiProblem.class,e->assertThat(e.code).isEqualTo("IDEMPOTENCY_CONFLICT"));}finally{pool.shutdownNow();}
    }
    @Test void simultaneousRequestsCannotExceedCustomerOrSpendReservation()throws Exception{
        List<UUID> sources=List.of(source(),source(),source());var pool=Executors.newFixedThreadPool(3);var go=new CountDownLatch(1);
        try{var calls=sources.stream().map(s->pool.submit(()->{as(owner);go.await();try{service.create(intent(s,UUID.randomUUID().toString()));return true;}catch(ApiProblem e){assertThat(e.status).isEqualTo(429);return false;}finally{SecurityContextHolder.clearContext();}})).toList();go.countDown();int won=0;for(var call:calls)if(call.get(10,TimeUnit.SECONDS))won++;assertThat(won).isEqualTo(2);assertThat(ledger("reserved_usd")).isEqualByComparingTo("0.50");as(owner);assertThat(tx.quota().get("used")).isEqualTo(2);}finally{pool.shutdownNow();}
    }
    @ParameterizedTest @ValueSource(ints={1,2}) void confirmedTransientResponseRetriesAtMostOnceAndOldDeliveryCannotClaimNewAttempt(int failures){UUID id=job();provider.failure=ProviderFailure.Kind.RETRYABLE;provider.failures.set(failures);SecurityContextHolder.clearContext();worker.run(id,1);as(owner);assertThat(service.get(id).get("state")).isEqualTo("QUEUED");assertThat(ledger("reserved_usd")).isEqualByComparingTo("0.25");assertThat(ledger("committed_usd")).isZero();worker.run(id,1);assertThat(provider.calls).hasValue(1);worker.run(id,2);worker.run(id,2);assertThat(provider.calls).hasValue(2);as(owner);assertThat(service.get(id).get("state")).isEqualTo(failures==1?"SUCCEEDED":"FAILED");assertThat(tx.quota().get("used")).isEqualTo(failures==1?1:0);}
    @Test void unknownOutcomeNeverAutomaticallyRetriesAndRefundsOnlyCustomerAllowance(){UUID id=job();provider.failure=ProviderFailure.Kind.UNKNOWN_OUTCOME;provider.failures.set(1);worker.run(id,1);worker.run(id,1);assertThat(provider.calls).hasValue(1);as(owner);assertThat(service.get(id).get("state")).isEqualTo("FAILED");@SuppressWarnings("unchecked")var error=(Map<String,Object>)service.get(id).get("error");assertThat(error.get("code")).isEqualTo("UNKNOWN_OUTCOME");assertThat(tx.quota().get("used")).isEqualTo(0);assertThat(ledger("committed_usd")).isEqualByComparingTo("0.25");assertThat(ledger("reserved_usd")).isZero();}
    @Test void acceptedGlobalRequestsRemainCountedAfterConfirmedUnbilledFailures(){provider.failure=ProviderFailure.Kind.REJECTED;provider.failures.set(4);for(int i=0;i<4;i++){UUID id=job();worker.run(id,1);as(owner);}assertThat(tx.quota().get("used")).isEqualTo(0);assertThat(ledger("committed_usd")).isZero();UUID fifth=source();assertThatThrownBy(()->service.create(intent(fifth,UUID.randomUUID().toString()))).isInstanceOfSatisfying(ApiProblem.class,e->assertThat(e.code).isEqualTo("GLOBAL_DAILY_LIMIT"));assertThat(provider.calls).hasValue(4);}
    @Test void concurrentOwnersCannotOverbookTheGlobalProviderBudget()throws Exception{
        var requests=new ArrayList<Map.Entry<UUID,UUID>>();for(UUID customer:List.of(owner,other)){as(customer);requests.add(Map.entry(customer,source()));requests.add(Map.entry(customer,source()));}var pool=Executors.newFixedThreadPool(4);var go=new CountDownLatch(1);try{var calls=requests.stream().map(request->pool.submit(()->{as(request.getKey());go.await();try{service.create(intent(request.getValue(),UUID.randomUUID().toString()));return true;}catch(ApiProblem e){assertThat(e.code).isEqualTo("PROVIDER_BUDGET_LIMIT");return false;}finally{SecurityContextHolder.clearContext();}})).toList();go.countDown();int won=0;for(var call:calls)if(call.get(10,TimeUnit.SECONDS))won++;assertThat(won).isEqualTo(2);assertThat(ledger("reserved_usd")).isEqualByComparingTo("0.50");}finally{pool.shutdownNow();}
    }
    @Test void staleConsentAfterQueueingCannotReachTheProvider(){UUID id=job();jdbc.update("UPDATE vw_tryon_consent SET version='previous-provider-disclosure' WHERE id=(SELECT consent_id FROM vw_private_media WHERE job_id=? AND purpose='SOURCE')",id);worker.run(id,1);assertThat(provider.calls).hasValue(0);as(owner);assertThat(service.get(id).get("state")).isEqualTo("FAILED");assertThat(ledger("reserved_usd")).isZero();assertThat(ledger("committed_usd")).isZero();assertThat(tx.quota().get("used")).isEqualTo(0);}
    @Test void queuedWorkKeepsTheGarmentReferenceSelectedAtCreation(){UUID original=jdbc.queryForObject("SELECT reference_media_id FROM vw_product WHERE id=?",UUID.class,product);UUID id=job();as(admin);var lease=catalogMedia.authorize(store,product,null,"PRODUCT_IMAGE",Map.of("kind","IMAGE","contentType","image/png","bytes",png.length));UUID replacement=(UUID)lease.get("uploadId");@SuppressWarnings("unchecked")var headers=(Map<String,String>)lease.get("headers");catalogMedia.upload(replacement,headers.get("X-Upload-Token"),"image/png",new ByteArrayInputStream(png),png.length);catalogMedia.finalizeUpload(replacement);catalog.patch(store,product,Map.of("referenceMediaId",replacement.toString()));var claim=tx.claim(id,1);assertThat(claim.reference()).isEqualTo(original);}
    @Test void failedEnqueueRemainsDurableAndReconciliationRegistersSameDelivery(){
        TaskDispatcher broken=(id,sequence)->{throw new IOException("Controlled dispatch failure");};var failedService=new TryOnService(tx,settings,storage,images,broken,rates,foundation);UUID id=(UUID)failedService.create(intent(source(),UUID.randomUUID().toString())).get("id");assertThat(jdbc.queryForObject("SELECT dispatched_at FROM vw_tryon_job WHERE id=?",java.sql.Timestamp.class,id)).isNull();service.reconcileDispatch();service.reconcileDispatch();assertThat(jdbc.queryForObject("SELECT count(*) FROM vw_task_delivery WHERE job_id=?",Integer.class,id)).isEqualTo(1);assertThat(ledger("reserved_usd")).isEqualByComparingTo("0.25");
    }
    @Test void failureBeforeAClaimIsNotAcknowledgedAndDoesNotLoseTheQueuedJob(){UUID id=job();var unavailable=new TryOnTransactions(jdbc,identity,settings){@Override public Claim claim(UUID job,int sequence){throw new IllegalStateException("Controlled database outage");}};var stopped=new TryOnWorker(unavailable,service,provider,storage,catalogMedia,images,settings);assertThat(stopped.run(id,1)).isFalse();assertThat(provider.calls).hasValue(0);as(owner);assertThat(service.get(id).get("state")).isEqualTo("QUEUED");worker.run(id,1);assertThat(provider.calls).hasValue(1);assertThat(service.get(id).get("state")).isEqualTo("SUCCEEDED");}
    @Test void confirmedProviderUsageSurvivesAnOutputStorageFailureAndCustomerIsRefunded(){UUID id=job();MediaStorage broken=new MediaStorage(){public void put(String key,byte[] bytes,String mime)throws IOException{throw new IOException("Controlled output storage failure");}public byte[] read(String key)throws IOException{return storage.read(key);}public void delete(String key)throws IOException{storage.delete(key);}};var failingWorker=new TryOnWorker(tx,service,provider,broken,catalogMedia,images,settings);assertThat(failingWorker.run(id,1)).isTrue();as(owner);assertThat(service.get(id).get("state")).isEqualTo("FAILED");assertThat(tx.quota().get("used")).isEqualTo(0);assertThat(ledger("observed_usd")).isEqualByComparingTo("0.04");assertThat(ledger("committed_usd")).isEqualByComparingTo("0.25");assertThat(provider.calls).hasValue(1);}
    @ParameterizedTest @ValueSource(strings={"CANCEL","DISCARD","ACCOUNT"})
    void cancellationDiscardOrAccountDeletionDuringProviderPreventsLateResurrection(String action)throws Exception{
        UUID id=job();provider.block=true;var pool=Executors.newSingleThreadExecutor();try{var call=pool.submit(()->worker.run(id,1));assertThat(provider.entered.await(5,TimeUnit.SECONDS)).isTrue();as(owner);if(action.equals("CANCEL"))tx.cancel(id);else if(action.equals("DISCARD"))service.discard(id);else identity.deleteCustomer(identity.find(owner),Map.of("password","ValidPassword123!","confirm",true));provider.release.countDown();assertThat(call.get(10,TimeUnit.SECONDS)).isTrue();assertThat(jdbc.queryForObject("SELECT state FROM vw_tryon_job WHERE id=?",String.class,id)).isEqualTo("CANCELLED");assertThat(jdbc.queryForObject("SELECT count(*) FROM vw_private_media WHERE owner_id=? AND state IN('ACTIVE','SAVING','SAVED')",Integer.class,owner)).isZero();assertThat(jdbc.queryForObject("SELECT used FROM vw_customer_generation_day WHERE owner_id=?",Integer.class,owner)).isZero();assertThat(ledger("committed_usd")).isEqualByComparingTo("0.25");assertThat(ledger("observed_usd")).isEqualByComparingTo("0.04");}finally{provider.release.countDown();pool.shutdownNow();}
    }
    @Test void interruptedStartedWorkExpiresAsUnknownWithoutRepeatingPaidCall(){UUID id=job();var claim=tx.claim(id,1);assertThat(tx.providerStarted(claim)).isTrue();jdbc.update("UPDATE vw_tryon_job SET deadline_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",id);service.maintenance();as(owner);assertThat(service.get(id).get("state")).isEqualTo("EXPIRED");@SuppressWarnings("unchecked")var error=(Map<String,Object>)service.get(id).get("error");assertThat(error.get("code")).isEqualTo("UNKNOWN_OUTCOME");assertThat(tx.quota().get("used")).isEqualTo(0);assertThat(ledger("committed_usd")).isEqualByComparingTo("0.25");worker.run(id,1);assertThat(provider.calls).hasValue(0);}
    @Test void concurrentGallerySavesRespectPendingSlotLimit()throws Exception{
        UUID a=job(),b=job();worker.run(a,1);worker.run(b,1);var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);try{var calls=List.of(a,b).stream().map(id->pool.submit(()->{as(owner);go.await();try{service.save(id);return true;}catch(ApiProblem e){assertThat(e.code).isEqualTo("GALLERY_FULL");return false;}finally{SecurityContextHolder.clearContext();}})).toList();go.countDown();int won=0;for(var call:calls)if(call.get(10,TimeUnit.SECONDS))won++;assertThat(won).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM vw_private_media WHERE state='SAVED'",Integer.class)).isEqualTo(1);}finally{pool.shutdownNow();}
    }
    @Test void interruptedSaveRecoversWithUniqueKeyAndLateOldCopyCannotReplaceNewSavedResult()throws Exception{
        UUID id=job();worker.run(id,1);as(owner);var interrupted=tx.beginSave(id);assertThat(interrupted.performCopy()).isTrue();var before=interrupted.media();byte[] bytes=storage.read(before.objectKey());assertThat(tx.quota().get("saved")).isEqualTo(1);
        jdbc.update("UPDATE vw_private_media SET saving_started_at=CURRENT_TIMESTAMP-INTERVAL '6 minutes' WHERE id=?",before.id());service.maintenance();assertThat(tx.media(before.id()).state()).isEqualTo("ACTIVE");assertThat(tx.quota().get("saved")).isEqualTo(0);service.save(id);var saved=tx.media(before.id());assertThat(saved.state()).isEqualTo("SAVED");assertThat(saved.objectKey()).isNotEqualTo(before.pendingKey());
        storage.put(before.pendingKey(),bytes,"image/jpeg");assertThat(tx.saved(before.id(),before.pendingKey())).isFalse();service.drainDeletes();assertThat(tx.media(before.id()).state()).isEqualTo("SAVED");assertThat(storage.read(saved.objectKey())).isNotEmpty();assertThatThrownBy(()->storage.read(before.pendingKey())).isInstanceOf(IOException.class);
    }
    @Test void deletionDuringSavedCopyWinsAndRemovesPendingSavedObject()throws Exception{
        UUID id=job(),second=job();worker.run(id,1);worker.run(second,1);as(owner);UUID output=(UUID)result(id).get("id");String original=tx.media(output).objectKey();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);
        MediaStorage slow=new MediaStorage(){public void put(String key,byte[] bytes,String mime)throws IOException{storage.put(key,bytes,mime);}public byte[] read(String key)throws IOException{byte[] value=storage.read(key);if(key.equals(original)){entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IOException();}catch(InterruptedException e){throw new IOException(e);}}return value;}public void delete(String key)throws IOException{storage.delete(key);}};
        var slowService=new TryOnService(tx,settings,slow,images,(j,s)->{},rates,foundation);var pool=Executors.newSingleThreadExecutor();try{var call=pool.submit(()->{as(owner);try{slowService.save(id);return 200;}catch(ApiProblem e){return e.status;}finally{SecurityContextHolder.clearContext();}});assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();as(owner);assertThatThrownBy(()->service.save(second)).isInstanceOfSatisfying(ApiProblem.class,e->assertThat(e.code).isEqualTo("GALLERY_FULL"));service.discard(id);release.countDown();assertThat(call.get(10,TimeUnit.SECONDS)).isIn(404,503);assertThat(tx.media(output).state()).isEqualTo("DELETED");assertThatThrownBy(()->storage.read(tx.media(output).pendingKey())).isInstanceOf(IOException.class);service.save(second);assertThat(tx.quota().get("saved")).isEqualTo(1);}finally{release.countDown();pool.shutdownNow();}
    }
    @Test void expiryAndDeletionFailureRemainRecoverableWithoutExpiringSavedOutputs()throws Exception{
        UUID a=job(),b=job();worker.run(a,1);worker.run(b,1);as(owner);service.save(a);UUID saved=(UUID)result(a).get("id"),unsaved=(UUID)result(b).get("id");jdbc.update("UPDATE vw_private_media SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",unsaved);assertThatThrownBy(()->service.read(unsaved,false)).isInstanceOf(ApiProblem.class);service.maintenance();assertThat(tx.media(unsaved).state()).isEqualTo("DELETED");assertThat(service.read(saved,false).getStatusCode().value()).isEqualTo(200);
        String key="source/"+owner+"/deletion-retry.jpg";storage.put(key,png,"image/png");tx.scheduleDelete(key);var fail=new AtomicInteger(1);MediaStorage flaky=new MediaStorage(){public void put(String k,byte[] b,String m)throws IOException{storage.put(k,b,m);}public byte[] read(String k)throws IOException{return storage.read(k);}public void delete(String k)throws IOException{if(k.equals(key)&&fail.getAndDecrement()>0)throw new IOException("Controlled storage failure");storage.delete(k);}};
        new TryOnService(tx,settings,flaky,images,(j,s)->{},rates,foundation).drainDeletes();assertThat(storage.read(key)).isNotEmpty();jdbc.update("UPDATE vw_object_deletion SET next_attempt_at=CURRENT_TIMESTAMP-INTERVAL '1 second',final_check_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE object_key=?",key);service.drainDeletes();assertThatThrownBy(()->storage.read(key)).isInstanceOf(IOException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM vw_object_deletion WHERE object_key=?",Integer.class,key)).isZero();
    }
